function showView(next,updateUrl=false){
  view=next==='workspace'&&!current?'home':next;
  $('#empty').hidden=view!=='home';$('#workspace').hidden=view!=='workspace';$('#source-guide').hidden=view!=='guide';
  $('#back-workspace').hidden=!current||view!=='guide';
  $('#home').classList.toggle('active',view==='home');$('#open-guide').classList.toggle('active',view==='guide');
  for(const [id,active] of [['home',view==='home'],['open-guide',view==='guide']]){if(active)$('#'+id).setAttribute('aria-current','page');else $('#'+id).removeAttribute('aria-current')}
  if(updateUrl)history.replaceState(null,'',location.pathname+location.search+(view==='guide'?'#source-guide':''));
}
