// A bounded, portable backup of saved projects and their linked files. No network providers are used.
const BACKUP_TOTAL=64*1024*1024, BACKUP_MAX_FILE=100*1024*1024;
function backupReferences(items){
 const ids=new Set();
 for(const p of items){if(!p||!Array.isArray(p.sources||[]))throw Error('مصادر المشروع غير صالحة');for(const s of (p.sources||[])){if(s.fileId){if(!/^[a-f0-9]{64}$/.test(s.fileId))throw Error('معرّف ملف مرتبط غير صالح');ids.add(s.fileId)}}}
 if(ids.size>100)throw Error('النسخة الشاملة تدعم حتى 100 ملف مرتبط');return ids;
}
function backupProjectCopies(items){
 if(!Array.isArray(items)||!items.length||items.length>100)throw Error('النسخة تدعم من مشروع واحد إلى 100 مشروع');
 const copies=items.map(p=>({...p,id:uid()}));
 if(new TextEncoder().encode(JSON.stringify({projects:copies})).length>5*1024*1024)throw Error('بيانات المشاريع أكبر من 5 ميبيبايت؛ قسّمها قبل النقل');
 return copies;
}
async function createFullBackup(){
 const saved=(await api('/api/projects')).projects;backupProjectCopies(saved);
 const ids=backupReferences(saved),files=[];let total=0;
 for(const id of ids){const file=(await api('/api/library/export',{id})).document;total+=file.size;if(total>BACKUP_TOTAL)throw Error('الملفات المرتبطة تتجاوز 64 ميبيبايت؛ احتفظ بمجلد البيانات والملفات الأصلية');files.push(file)}
 return {format:'sanad-backup',version:2,projects:saved,files};
}
async function validateBackupFiles(obj){
 const ids=backupReferences(obj.projects);if(!Array.isArray(obj.files)||obj.files.length!==ids.size)throw Error('النسخة لا تحتوي جميع الملفات المرتبطة');
 const found=new Set();let total=0;
 for(const file of obj.files){
  if(!file||typeof file.id!=='string'||!ids.has(file.id)||found.has(file.id)||typeof file.name!=='string'||!/^([a-f0-9]{64})\.(txt|pdf)$/.test(file.name)||!file.name.startsWith(file.id+'.')||!Number.isSafeInteger(file.size)||file.size<1||file.size>20*1024*1024||typeof file.content!=='string'||file.content.length>20*1024*1024*4/3+16||!/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(file.content))throw Error('بيانات ملف في النسخة غير صالحة');
  total+=file.size;if(total>BACKUP_TOTAL)throw Error('الملفات المرتبطة تتجاوز 64 ميبيبايت');
  let raw;try{raw=atob(file.content)}catch{throw Error('ترميز ملف في النسخة غير صالح')}
  if(raw.length!==file.size||btoa(raw)!==file.content)throw Error('حجم الملف أو ترميزه لا يطابق النسخة');
  const bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));
  const hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),b=>b.toString(16).padStart(2,'0')).join('');
  if(hash!==file.id)throw Error('بصمة ملف لا تطابق بياناته؛ لم تُستورد المشاريع');found.add(file.id);
 }
}
async function restoreBackup(obj){
 if(!obj||obj.format!=='sanad-backup'||![1,2].includes(obj.version))throw Error('ملف نسخة احتياطية غير صالح');
 const copies=backupProjectCopies(obj.projects);backupReferences(copies);
 if(obj.version===2){
  await validateBackupFiles(obj);
  for(const file of obj.files){const doc=(await api('/api/library/import',{name:file.name,content:file.content})).document;if(doc.id!==file.id)throw Error('بصمة الملف المستورد غير مطابقة')}
 }
 await api('/api/projects/import',{projects:copies});return copies.length;
}
$('#export-all').onclick=async e=>{
 if(dirty)return alertToast('احفظ المشروع أولًا قبل إنشاء النسخة الشاملة');
 if(!confirm('ستشمل النسخة المشاريع المحفوظة وملفات المصادر المرتبطة بها فقط، حتى 64 ميبيبايت و100 ملف. الملف غير مشفر وقد يحتوي مواد خاصة؛ احفظه في مكان آمن. هل تتابع؟'))return;
 const button=e.currentTarget;button.disabled=true;
 try{const obj=await createFullBackup();download('sanad-backup-with-files.json',obj);alertToast(`أُنشئت نسخة تشمل ${obj.projects.length} مشروعًا و${obj.files.length} ملفًا مرتبطًا`)}catch(err){alertToast('تعذر إنشاء النسخة: '+err.message)}finally{button.disabled=false}
};
$('#import').onchange=async e=>{
 const f=e.target.files[0];if(!f)return;if(dirty){alertToast('احفظ التغييرات قبل الاستيراد');e.target.value='';return}
 try{
  if(f.size>BACKUP_MAX_FILE)throw Error('ملف النسخة أكبر من 100 ميبيبايت');const obj=JSON.parse(await f.text());
  if(!obj||obj.format!=='sanad-backup'||![1,2].includes(obj.version)||!Array.isArray(obj.projects))throw Error('ملف نسخة احتياطية غير صالح');
  if(!confirm(`استيراد ${obj.projects.length} مشروعًا كنسخ جديدة دون استبدال الحالية؟ ${obj.version===1?'هذه نسخة قديمة لا تتضمن ملفات؛ قد تحتاج إعادة ربطها.':'ستُفحص الملفات المرتبطة وبصماتها قبل حفظ المشاريع.'}`))return;
  const count=await restoreBackup(obj);projects=(await api('/api/projects')).projects;render();alertToast(`استُورد ${count} مشروعًا كنسخ جديدة${obj.version===1?'؛ النسخة القديمة لا تتضمن الملفات':''}`);
 }catch(err){alertToast('تعذر الاستيراد: '+err.message+' — لم تُستبدل المشاريع الحالية؛ قد تبقى ملفات غير مرتبطة إذا تعذّر الحفظ.')}finally{e.target.value=''}
};
